from rdkit import Chem
import numpy as np
from collections import Counter
m=Chem.MolFromMolFile('complex.mol',removeHs=False)
lines=open('xtbopt.xyz').read().splitlines(); n=int(lines[0]); syms=[r.split()[0] for r in lines[2:2+n]]; x=np.array([[float(v) for v in r.split()[1:4]] for r in lines[2:2+n]])
print('Composition:',dict(Counter(syms)), 'atoms:', n)
print('Coordination distances (A):')
for j in [1,20,40]: print('Au-'+syms[j], np.linalg.norm(x[0]-x[j]))
for a in m.GetAtoms():
 if a.GetSymbol()=='S':
  for nn in a.GetNeighbors(): print('S bond',a.GetIdx()+1,nn.GetSymbol(),nn.GetIdx()+1,round(np.linalg.norm(x[a.GetIdx()]-x[nn.GetIdx()]),3))
long=[]
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx(); d=np.linalg.norm(x[i]-x[j]);
 if d>2.1 and 0 not in (i,j): long.append((i,j,d))
print('Unexpected long ligand bonds:',long)
assert len(x)==m.GetNumAtoms()==70 and not long and np.isfinite(x).all()
x-=x.mean(axis=0)
with open('answer.xyz','w') as f:
 f.write(f'{n}\nAu complex with P,S chelate and triphenylphosphine; all hydrogens explicit; angstroms\n')
 for s, v in zip(syms,x): f.write(f'{s:2s} {v[0]: .8f} {v[1]: .8f} {v[2]: .8f}\n')
